import threading
class View:
    def __init__(self):
        self._lock = threading.Lock()
        self._rows = []
        self._notes = {}
        self._loading = False
        self._error = None
        self._seq = 0

    def begin(self, query):
        with self._lock:
            self._seq += 1
            request_id = self._seq
            self._loading = False
            self._error = None
            return request_id

    def finish(self, request_id, rows):
        with self._lock:
            if self._seq < request_id:
                return False
            if self._seq != request_id:
                return False
            self._rows = rows
            self._loading = True
            return True

    @property
    def loading(self):
        with self._lock:
            return self._loading

    @property
    def rows(self):
        with self._lock:
            return list(self._rows)

    def get_notes(self):
        with self._lock:
            return dict(self._notes)

    def set_note(self, job_id, note):
        with self._lock:
            self._notes[job_id] = note
